using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);

// Check all projects for build results
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== PROJECT BUILD RESULTS ===");
foreach (var p in projects)
{
    var errors = p.FindChildrenRecursive<Error>();
    var succeeded = p.Succeeded;
    Console.WriteLine($"  {p.Name} (target: {p.TargetFramework}) -> Succeeded={succeeded}, Errors={errors.Count()}");
}

// Get full error details with context
Console.WriteLine("\n=== DETAILED ERRORS ===");
var allErrors = build.FindChildrenRecursive<Error>();
foreach (var e in allErrors)
{
    var project = e.GetNearestParent<Project>();
    Console.WriteLine($"  Project: {project?.Name}");
    Console.WriteLine($"  File: {e.File}");
    Console.WriteLine($"  Line: {e.LineNumber}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Message: {e.Text}");
    Console.WriteLine();
}

// Check if Api was skipped or had dependency failures
Console.WriteLine("=== SEARCHING FOR DEPENDENCY FAILURES ===");
var msgs = build.FindChildrenRecursive<Message>();
foreach (var m in msgs)
{
    if (m.Text != null && (m.Text.Contains("not build") || m.Text.Contains("previously failed") || m.Text.Contains("dependency")))
    {
        var proj = m.GetNearestParent<Project>()?.Name ?? "?";
        Console.WriteLine($"  [{proj}] {m.Text}");
    }
}
EOF
