using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);

// Look for the build target results more carefully
Console.WriteLine("=== SEARCHING FOR BUILD FAILURE MESSAGES ===");
var msgs = build.FindChildrenRecursive<Message>();
foreach (var m in msgs)
{
    if (m.Text != null && (m.Text.Contains("Build FAILED") || m.Text.Contains("previously") || 
        m.Text.Contains("did not build") || m.Text.Contains("skipping")))
    {
        var proj = m.GetNearestParent<Project>()?.Name ?? "?";
        Console.WriteLine($"  [{proj}] {m.Text}");
    }
}

// Check the Api project specifically - did its compile target run?
Console.WriteLine("\n=== API PROJECT TARGETS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (p.Name == "Api.csproj")
    {
        var targets = p.FindChildrenRecursive<Target>();
        foreach (var t in targets)
        {
            if (t.Name == "CoreCompile" || t.Name == "Build" || t.Name == "ResolveProjectReferences")
            {
                Console.WriteLine($"  Target: {t.Name}");
            }
        }
    }
}

// Look at the UserService.cs content from the Csc command line
Console.WriteLine("\n=== CSC COMMAND FOR SERVICES ===");
var tasks = build.FindChildrenRecursive<Task>();
foreach (var t in tasks)
{
    if (t.Name == "Csc")
    {
        var proj = t.GetNearestParent<Project>()?.Name;
        if (proj == "Services.csproj")
        {
            var children = t.Children;
            foreach (var c in children)
            {
                if (c is Message msg && msg.Text != null && msg.Text.Contains("csc"))
                {
                    // Just get references portion
                    var text = msg.Text;
                    var refStart = text.IndexOf("/reference:");
                    if (refStart >= 0)
                    {
                        Console.WriteLine("  References passed to csc (first 500 chars of refs):");
                        var refsText = text.Substring(refStart);
                        Console.WriteLine("  " + refsText.Substring(0, Math.Min(500, refsText.Length)));
                    }
                    break;
                }
            }
        }
    }
}
EOF
