            foreach (var p in props)
            {
                if (p.Name == "References" || p.Name == "Sources")
                    Console.WriteLine($"  {p.Name}: {p.Value}");
            }
            // Check items
            var items = t.FindChildrenRecursive<Item>();
            foreach (var item in items)
            {
                Console.WriteLine($"  Item: {item.Name} = {item.Text}");
            }
            break;
        }
    }
}

